use super::{native_roof_callback_study as roof,native_appearance_inspection as a,native_appearance_replay_study_tests as fixture,native_resources as r,world_map::WorldCell};
use std::{fs,path::{Path,PathBuf},sync::atomic::AtomicBool};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn sha(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}fn digest(s:&str)->[u8;32]{(0..32).map(|i|u8::from_str_radix(&s[i*2..i*2+2],16).unwrap()).collect::<Vec<_>>().try_into().unwrap()}fn byte_pin(v:&Value)->r::BytePin{r::BytePin{bytes:v["bytes"].as_u64().unwrap(),sha256:digest(v["sha256"].as_str().unwrap())}}fn pin(path:&Path)->Value{let b=fs::read(path).unwrap();json!({"path":path,"bytes":b.len(),"sha256":sha(&b)})}
pub(super) fn assets()->(r::NativeStaticAssets,r::NativeAssetPlan,Vec<Value>){let project=Path::new(env!("CARGO_MANIFEST_DIR"));let provider_path=project.join("target/r425-native-dm564-fixture/consumer-input.json");let provider:Value=serde_json::from_slice(&fs::read(&provider_path).unwrap()).unwrap();let archives=provider["archive_pins"].as_array().unwrap();let map_path=PathBuf::from(provider["native_map"]["path"].as_str().unwrap());let roots=r::NativeSources{map_root:map_path.parent().unwrap().parent().unwrap().to_owned(),archive_root:PathBuf::from(archives[0]["path"].as_str().unwrap()).parent().unwrap().to_owned()};let plan=r::NativeAssetPlan{namespace:r::ResourceNamespace::NativeLitoV1,map_id:564,canonical_sha256:digest(provider["native_map"]["canonical_sha256"].as_str().unwrap()),sectors:vec![r::SectorPin{key:r::NativeSectorKey{map_id:564,x:0x7fff,y:0x8000},pin:byte_pin(&provider["native_map"])}],archives:archives.iter().zip([r::ArchiveRole::TileIndex,r::ArchiveRole::TilePak,r::ArchiveRole::SpriteIndex,r::ArchiveRole::SpritePak]).map(|(v,role)|r::ArchivePin{role,pin:byte_pin(v)}).collect()};let assets=r::NativeResourceAdapter::pinned_inspection().load_static(&roots,&plan,Default::default(),&AtomicBool::new(false)).unwrap();let mut pins=vec![pin(&provider_path),pin(&map_path)];for v in archives{pins.push(pin(Path::new(v["path"].as_str().unwrap())));} (assets,plan,pins)}
fn inputs(old:WorldCell,new:WorldCell,sample:u32)->roof::Inputs{roof::Inputs{local_actor_pointer_matches:Some(true),old_cell:Some(old),new_cell:Some(new),no_dynamic_cell_entries:Some(true),source_initialized_tiles:Some(true),scheduler_sample_ms:Some(sample)}}
fn tick(dispatch:u32,sample:u32)->roof::Tick{roof::Tick{timer_removed_before_callback:Some(true),callback_group_matches:Some(true),dispatch_ms:Some(dispatch),scheduler_sample_ms:Some(sample)}}
#[test]fn settled_roof_actor_writes_refuse_backward_missing_wrapping_clocks_atomically(){
 let project=Path::new(env!("CARGO_MANIFEST_DIR"));let fixed=fixture::Fixed::new();let bindings=a::nab(&fixed.bytes("evidence/appearance-bindings.nab")).unwrap();let b=&bindings[3];let(assets,plan,extra)=assets();let key=assets.geometry().bindings()[0].key;let sector=assets.geometry().sector(key).unwrap();let(ox,oy)=key.world_origin();let outside=(0..64).flat_map(|y|(0..64).map(move|x|WorldCell{x:ox+x,y:oy+y})).find(|c|!sector.opacity.iter().any(|r|r.x<128&&r.y<64&&i32::from(r.x)==2*(c.x-ox)&&i32::from(r.y)==c.y-oy)).unwrap();let inside=WorldCell{x:32720,y:32804};let mut initial=inputs(outside,inside,500);initial.scheduler_sample_ms=None;assert!(roof::Model::new(true,b,b,b.observed,&assets,&plan,outside,133,16,&initial).is_err());let mut model=roof::Model::new(true,b,b,b.observed,&assets,&plan,outside,133,16,&inputs(outside,inside,500)).unwrap();model.move_actor(b,b.observed,&inputs(outside,inside,500)).unwrap();for expected_due in [550,600,650,700]{assert_eq!(model.due(b,b.observed).unwrap(),expected_due);model.callback(b,b.observed,&tick(expected_due,expected_due)).unwrap();}assert_eq!(model.clock(b,b.observed).unwrap(),700);assert!(model.due(b,b.observed).is_err());let settled=model.states();
 for sample in [Some(699),None,Some(u32::MAX)]{let mut q=inputs(inside,outside,701);q.scheduler_sample_ms=sample;assert!(model.move_actor(b,b.observed,&q).is_err());assert_eq!(model.states(),settled);assert_eq!(model.clock(b,b.observed).unwrap(),700);assert!(model.due(b,b.observed).is_err());}model.move_actor(b,b.observed,&inputs(inside,outside,701)).unwrap();for expected_due in [751,801,851,901]{assert_eq!(model.due(b,b.observed).unwrap(),expected_due);model.callback(b,b.observed,&tick(expected_due,expected_due)).unwrap();}let restored=model.states();assert_eq!(model.clock(b,b.observed).unwrap(),901);assert!(model.move_actor(b,b.observed,&inputs(outside,inside,900)).is_err());assert_eq!(model.states(),restored);assert_eq!(model.clock(b,b.observed).unwrap(),901);assert!(model.due(b,b.observed).is_err());model.move_actor(b,b.observed,&inputs(outside,inside,902)).unwrap();assert_eq!(model.due(b,b.observed).unwrap(),952);model.retire();assert!(model.clock(b,b.observed).is_err());assert!(model.due(b,b.observed).is_err());
 fs::write(project.join("logs/continuation-20261003/r455-roof-clock-guard-details.json"),serde_json::to_vec_pretty(&json!({"state":"PASSED_SETTLED_ROOF_ACTOR_CLOCK_WRITE_GUARD","missing_initial_clock_refused":true,"backward699_after700_refused":true,"missing_write_clock_refused":true,"wrapping_write_clock_refused":true,"backward900_after901_refused":true,"failed_write_preserves_clock_flags_and_timer":true,"accepted_fresh_write_902_due952":true,"retire_revokes_clock_read":true,"input_pins":fixed.used.into_inner(),"extra_input_pins":extra,"runtime_inputs_observed":false,"renderer_LOADED":false,"GUI":0,"new_CPU_images":0,"reason_no_new_CPU_images":"Focused clock-guard correction; R453 and R454 immutable CPU evidence retained"})).unwrap()).unwrap();
}
#[test]fn native564_pointer_alias_actor_half_roof_callbacks_late_once_restore_retire(){
 let project=Path::new(env!("CARGO_MANIFEST_DIR"));let fixed=fixture::Fixed::new();let bindings=a::nab(&fixed.bytes("evidence/appearance-bindings.nab")).unwrap();let b=&bindings[3];let(assets,plan,extra)=assets();let geometry=assets.geometry();let key=geometry.bindings()[0].key;let sector=geometry.sector(key).unwrap();let(ox,oy)=key.world_origin();let outside=(0..64).flat_map(|y|(0..64).map(move|x|WorldCell{x:ox+x,y:oy+y})).find(|c|!sector.opacity.iter().any(|r|r.x<128&&r.y<64&&i32::from(r.x)==2*(c.x-ox)&&i32::from(r.y)==c.y-oy)).unwrap();
 let selected=sector.opacity.iter().find(|record|record.kind==0&&record.x%2==0&&sector.opacity.iter().filter(|r|r.x==record.x&&r.y==record.y).count()==1&&!sector.objects[usize::from(record.object_index)].tiles.is_empty()&&sector.objects[usize::from(record.object_index)].tiles.iter().any(|t|(assets.scene_tiles()[&(t.tile_id as u16,t.subtile)].tile_type as u8)&4==0)).unwrap();let group=usize::from(selected.object_index);let inside=WorldCell{x:ox+i32::from(selected.x/2),y:oy+i32::from(selected.y)};let q=inputs(outside,inside,500);assert!(roof::Model::new(false,b,b,b.observed,&assets,&plan,outside,group,16,&q).is_err());let mut model=roof::Model::new(true,b,b,b.observed,&assets,&plan,outside,group,16,&q).unwrap();assert!(model.trigger().is_ok());let initial=model.states();let alias=model.alias_counts();assert_eq!(alias.0,61);let(ga,gb,id)=model.alias_pair().unwrap();let pa=model.read_group(b,b.observed,ga).unwrap();let pb=model.read_group(b,b.observed,gb).unwrap();assert!(pa.iter().any(|(p,_)|*p==id)&&pb.iter().any(|(p,_)|*p==id));
 let out=project.join("target/r453-native-roof-source-cpu");fs::create_dir_all(&out).unwrap();let baseline=model.render(b,b.observed,inside).unwrap();let mut images=vec![fixture::png(&out.join("roof-source-initial.png"),baseline.rgba(),512,384)];let mut rows=Vec::new();
 for i in 0..6{let mut missing=inputs(outside,inside,500);match i{0=>missing.local_actor_pointer_matches=None,1=>missing.old_cell=None,2=>missing.new_cell=None,3=>missing.no_dynamic_cell_entries=None,4=>missing.source_initialized_tiles=None,_=>missing.scheduler_sample_ms=None};assert!(model.move_actor(b,b.observed,&missing).is_err());assert!(model.due(b,b.observed).is_err());assert_eq!(model.states(),initial);}
 model.move_actor(b,b.observed,&q).unwrap();assert_eq!(model.due(b,b.observed).unwrap(),550);assert!(model.states().iter().zip(&initial).all(|(s,base)|s.flags==base.flags|0x400&&s.weight==if base.flags&0x100!=0{16}else{31}&&s.target==1));
 for i in 0..4{let mut missing=tick(1000,1007);match i{0=>missing.timer_removed_before_callback=None,1=>missing.callback_group_matches=None,2=>missing.dispatch_ms=None,_=>missing.scheduler_sample_ms=None};assert!(model.callback(b,b.observed,&missing).is_err());assert_eq!(model.due(b,b.observed).unwrap(),550);assert!(model.states().iter().zip(&initial).all(|(s,base)|s.weight==if base.flags&0x100!=0{16}else{31}));}
 for(step,expected)in [27,23,19,0].into_iter().enumerate(){let dispatch=if step==0{1000}else{model.due(b,b.observed).unwrap()};let sample=if step==0{1007}else{dispatch};model.callback(b,b.observed,&tick(dispatch,sample)).unwrap();let states=model.states();assert!(states.iter().zip(&initial).all(|(s,base)|s.weight==if base.flags&0x100!=0{0}else{expected}));let canvas=model.render(b,b.observed,inside).unwrap();images.push(fixture::png(&out.join(format!("roof-down-step{}-weight{expected}.png",step+1)),canvas.rgba(),512,384));rows.push(json!({"phase":"down","dispatch_ms":dispatch,"fresh_scheduler_ms":sample,"weights":states.iter().map(|s|s.weight).collect::<Vec<_>>(),"flags":states.iter().map(|s|s.flags).collect::<Vec<_>>(),"next_due_ms":model.due(b,b.observed).ok(),"RGBA_sha256":sha(canvas.rgba())}));}
 assert!(model.states().iter().zip(&initial).all(|(s,base)|s.flags==base.flags|1&&s.target==1));assert!(model.due(b,b.observed).is_err());assert_ne!(images[0]["RGBA_sha256"],images[4]["RGBA_sha256"]);model.move_actor(b,b.observed,&inputs(inside,outside,1200)).unwrap();assert_eq!(model.due(b,b.observed).unwrap(),1250);
 for(step,expected)in [21,25,29,0].into_iter().enumerate(){let dispatch=model.due(b,b.observed).unwrap();model.callback(b,b.observed,&tick(dispatch,dispatch)).unwrap();let states=model.states();assert!(states.iter().zip(&initial).all(|(s,base)|s.weight==if base.flags&0x100!=0{0}else{expected}));let canvas=model.render(b,b.observed,inside).unwrap();images.push(fixture::png(&out.join(format!("roof-up-step{}-weight{expected}.png",step+1)),canvas.rgba(),512,384));rows.push(json!({"phase":"up","dispatch_ms":dispatch,"weights":states.iter().map(|s|s.weight).collect::<Vec<_>>(),"flags":states.iter().map(|s|s.flags).collect::<Vec<_>>(),"next_due_ms":model.due(b,b.observed).ok(),"RGBA_sha256":sha(canvas.rgba())}));}
 assert!(model.states().iter().zip(&initial).all(|(s,base)|s.flags==if base.flags&0x100!=0{base.flags|1}else{base.flags}&&s.weight==0&&s.target==0));assert_eq!(images[0]["RGBA_sha256"],images[8]["RGBA_sha256"]);let mut foreign=b.clone();foreign.epoch+=1;assert!(model.read_group(&foreign,b.observed,group).is_err());model.move_actor(b,b.observed,&inputs(outside,inside,1500)).unwrap();assert_eq!(model.due(b,b.observed).unwrap(),1550);model.retire();assert!(model.due(b,b.observed).is_err());assert!(model.callback(b,b.observed,&tick(1550,1550)).is_err());assert!(model.read_group(b,b.observed,group).is_err());
 fs::write(project.join("logs/continuation-20261003/r453-roof-details.json"),serde_json::to_vec_pretty(&json!({"state":"FINITE_SOURCE_TILE_POINTER_ALIAS_SINGLE_ACTOR_HALF_ROOF_CALLBACK_CHAIN","group":group,"initial_flags":initial.iter().map(|s|s.flags).collect::<Vec<_>>(),"actual_effect_roof_raw_prepared":true,"conditional_inside":[inside.x,inside.y],"conditional_outside":[outside.x,outside.y],"alias_keys":alias.0,"alias_group_references":alias.1,"alias_sample":{"groups":[ga,gb],"resident_draw_id":id},"rows":rows,"missing_move_cases":6,"missing_callback_cases":4,"late_callback_catches_up":false,"retire_cancels_pending":true,"retire_revokes_read":true,"restored_RGBA_equals_initial":true,"input_pins":fixed.used.into_inner(),"extra_input_pins":extra,"images":images,"runtime_inputs_observed":false,"renderer_LOADED":false,"GUI":0,"Layer8_included":false})).unwrap()).unwrap();
}
